CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, verified INTEGER NOT NULL DEFAULT 0, verification_token TEXT, pending_email TEXT, pending_token TEXT);
CREATE TABLE IF NOT EXISTS preferences (owner_id INTEGER PRIMARY KEY REFERENCES users(id), timezone TEXT NOT NULL DEFAULT 'UTC', reminder_time TEXT NOT NULL DEFAULT '09:00', paused INTEGER NOT NULL DEFAULT 0, soon_days INTEGER NOT NULL DEFAULT 3, estimate_rules TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'other', image_path TEXT, image_data BLOB, image_mime TEXT, nutrition_json TEXT NOT NULL DEFAULT '{}', nutrition_basis TEXT, use_rate REAL, use_unit TEXT, UNIQUE(owner_id,name));
CREATE TABLE IF NOT EXISTS shopping (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, quantity REAL NOT NULL, unit TEXT NOT NULL, checked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS batches (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity REAL NOT NULL, remaining_quantity REAL NOT NULL, unit TEXT NOT NULL, purchase_date TEXT NOT NULL, storage TEXT NOT NULL, expiry_date TEXT NOT NULL, expiry_source TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), batch_id INTEGER NOT NULL REFERENCES batches(id), quantity_change REAL NOT NULL, reason TEXT NOT NULL, occurred_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reminders (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id), local_date TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, sent_at TEXT, error TEXT, UNIQUE(owner_id,local_date));
